   }

   computeShippingCents(
     lines: readonly CartLine[],
     subtotalCents: number,
   ): number {
     if (lines.length === 0) return 0;
     if (this.freeOverCents !== undefined && subtotalCents >= this.freeOverCents) {
       return 0;
     }
     return this.flatCents;
   }
 }

