    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      const p = product("a", 1000);
      cart.add(p, 2);
      const snap = cart.snapshot();
      // Mutate snapshot — cart should be unaffected
      snap[0]!.quantity = 99;
      snap[0]!.product.unitPriceCents = 1;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount then taxes on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();

      expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
      // Tax computed on discounted subtotal (1000 - 200 = 800)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      expect(totals.taxCents).toBe(80);
      expect(totals.totalCents).toBe(1000 - 200 + 80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000); // clamped to subtotal
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("shipping receives discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      cart.totals();
      // shipping gets discounted subtotal: 1000 - 300 = 700
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("uses custom region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("total = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 50,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 30,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // total = (1000 - 100) + 50 + 30 = 980
      expect(totals.totalCents).toBe(980);
    });
  });

  describe("defaults", () => {
    it("uses NoDiscountPolicy, NoTaxCalculator, FreeShippingCalculator, US region", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, priceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
});

describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher errors", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(checker.check).toHaveBeenCalledWith("p1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks inventory for all lines and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      cart.add(product("p2", 2000), 1);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "p2 gone" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("p2");
      }
    });
  });

  describe("async tax provider", () => {
    it("computes tax via asyncTaxProvider", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("p1", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
      // 8.75% of 10000 = 875
      expect(result.totals.taxCents).toBe(875);
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        region: "US",
      });
      cart.add(product("p1", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // Discount: 10% of 10000 = 1000, discounted subtotal = 9000
      // Tax: 10% of 9000 = 900
      expect(result.totals.discountCents).toBe(1000);
      expect(result.totals.taxCents).toBe(900);
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service error")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service error",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("refreshes prices, checks inventory, and computes totals with async tax + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(product("p1", 999), 2); // old price, will be refreshed

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // Subtotal: 1000 * 2 = 2000
      expect(result.totals.subtotalCents).toBe(2000);
      // Discount: 20% of 2000 = 400
      expect(result.totals.discountCents).toBe(400);
      // Tax: 10% of (2000 - 400) = 10% of 1600 = 160
      expect(result.totals.taxCents).toBe(160);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total: 1600 + 160 + 500 = 2260
      expect(result.totals.totalCents).toBe(2260);
    });

    it("works with no collaborators (sync fallback)", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("returns lines snapshot in the result", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("p1");
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, expectedMsg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(expectedMsg);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
    ])("%i%% of %i cents = %i cents", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 1001 = 330.33 → 330
      expect(policy.computeDiscountCents(1001)).toBe(330);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "amountCents must be a non-negative integer"],
      [1.5, "amountCents must be a non-negative integer"],
    ])("rejects invalid amountCents %s", (amount, expectedMsg) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(expectedMsg);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1500);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amounts match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can produce total exceeding subtotal (clamped by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // sum mode: 800 + 500 = 1300 (exceeds 1000 subtotal, Cart clamps)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800), // 800 → remaining 200
          new FixedAmountDiscountPolicy(500), // min(500, 200) = 200 → remaining 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters: larger discount first gives different result", () => {
      const policiesA = [
        new PercentageDiscountPolicy(50),
        new FixedAmountDiscountPolicy(100),
      ];
      const policiesB = [
        new FixedAmountDiscountPolicy(100),
        new PercentageDiscountPolicy(50),
      ];
      const a = new CompositeDiscountPolicy(policiesA, "chain");
      const b = new CompositeDiscountPolicy(policiesB, "chain");

      // A: 50% of 1000=500, then fixed 100 on 500 → 600
      // B: fixed 100 on 1000, then 50% of 900=450 → 550
      expect(a.computeDiscountCents(1000)).toBe(600);
      expect(b.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // -100 clamped to 0, then 200 on 1000 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

