import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, priceCents: number, weightGrams?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.itemCount).toBe(1);
    });

    it("merges quantities when adding same product twice", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      const p = product("a", 1000);
      cart.add(p, 2);
      const snap = cart.snapshot();
      // Mutate snapshot — cart should be unaffected
      snap[0]!.quantity = 99;
      snap[0]!.product.unitPriceCents = 1;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount then taxes on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();

      expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
      // Tax computed on discounted subtotal (1000 - 200 = 800)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      expect(totals.taxCents).toBe(80);
      expect(totals.totalCents).toBe(1000 - 200 + 80);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000); // clamped to subtotal
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("shipping receives discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      cart.totals();
      // shipping gets discounted subtotal: 1000 - 300 = 700
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        700,
      );
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("uses custom region for tax", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product("a", 1000), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("total = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 50,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 30,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // total = (1000 - 100) + 50 + 30 = 980
      expect(totals.totalCents).toBe(980);
    });
  });

  describe("defaults", () => {
    it("uses NoDiscountPolicy, NoTaxCalculator, FreeShippingCalculator, US region", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, priceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
});

describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher errors", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(checker.check).toHaveBeenCalledWith("p1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
