        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can produce total exceeding subtotal (clamped by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // sum mode: 800 + 500 = 1300 (exceeds 1000 subtotal, Cart clamps)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800), // 800 → remaining 200
          new FixedAmountDiscountPolicy(500), // min(500, 200) = 200 → remaining 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters: larger discount first gives different result", () => {
      const policiesA = [
        new PercentageDiscountPolicy(50),
        new FixedAmountDiscountPolicy(100),
      ];
      const policiesB = [
        new FixedAmountDiscountPolicy(100),
        new PercentageDiscountPolicy(50),
      ];
      const a = new CompositeDiscountPolicy(policiesA, "chain");
      const b = new CompositeDiscountPolicy(policiesB, "chain");

      // A: 50% of 1000=500, then fixed 100 on 500 → 600
      // B: fixed 100 on 1000, then 50% of 900=450 → 550
      expect(a.computeDiscountCents(1000)).toBe(600);
      expect(b.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // -100 clamped to 0, then 200 on 1000 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
