import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.1)).toThrow(RangeError);
    });

    it("rejects default rate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ FR: -0.01 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 1001 = 200.2 → 200
      expect(calc.computeTaxCents(1001, "FR")).toBe(200);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "FR")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "FR")).toBe(0);
    });

    it("uses default rate 0 when no default provided", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

