import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, priceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
});

describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher errors", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(checker.check).toHaveBeenCalledWith("p1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks inventory for all lines and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      cart.add(product("p2", 2000), 1);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "p2 gone" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("p2");
      }
    });
  });

  describe("async tax provider", () => {
    it("computes tax via asyncTaxProvider", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("p1", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
      // 8.75% of 10000 = 875
      expect(result.totals.taxCents).toBe(875);
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        region: "US",
      });
      cart.add(product("p1", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // Discount: 10% of 10000 = 1000, discounted subtotal = 9000
      // Tax: 10% of 9000 = 900
      expect(result.totals.discountCents).toBe(1000);
      expect(result.totals.taxCents).toBe(900);
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service error")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service error",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("refreshes prices, checks inventory, and computes totals with async tax + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(product("p1", 999), 2); // old price, will be refreshed

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // Subtotal: 1000 * 2 = 2000
      expect(result.totals.subtotalCents).toBe(2000);
      // Discount: 20% of 2000 = 400
      expect(result.totals.discountCents).toBe(400);
      // Tax: 10% of (2000 - 400) = 10% of 1600 = 160
      expect(result.totals.taxCents).toBe(160);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total: 1600 + 160 + 500 = 2260
      expect(result.totals.totalCents).toBe(2260);
    });

    it("works with no collaborators (sync fallback)", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("returns lines snapshot in the result", async () => {
      const cart = new Cart();
      cart.add(product("p1", 1000), 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("p1");
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });
});

